   319    if (hdr[7] & MQTT_HAS_WILL) {
   320      if (c->is_mqtt5 &&
   321          !mg_send_mqtt_properties(c, opts->will_props, opts->num_will_props))
   322        goto fail;
   323
   324      if (!mg_send_u16(c, mg_htons((uint16_t) opts->topic.len)) ||
   325          !mg_send(c, opts->topic.buf, opts->topic.len) ||
   326          !mg_send_u16(c, mg_htons((uint16_t) opts->message.len)) ||
   327          !mg_send(c, opts->message.buf, opts->message.len))
   328        goto fail;
   329    }
   330    if (opts->user.len > 0 &&
   331        (!mg_send_u16(c, mg_htons((uint16_t) opts->user.len)) ||
   332         !mg_send(c, opts->user.buf, opts->user.len)))
   333      goto fail;
   334    if (opts->pass.len > 0 &&
   335        (!mg_send_u16(c, mg_htons((uint16_t) opts->pass.len)) ||
   336         !mg_send(c, opts->pass.buf, opts->pass.len)))
   337      goto fail;
   338    return;
   339  fail:
   340    mg_error(c, "OOM");
   341  }
