   343  uint16_t mg_mqtt_pub(struct mg_connection *c, const struct mg_mqtt_opts *opts) {
   344    uint16_t id = opts->retransmit_id;
   345    uint8_t flags = (uint8_t) (((opts->qos & 3) << 1) | (opts->retain ? 1 : 0));
   346    size_t len = 2 + opts->topic.len + opts->message.len;
   347    MG_DEBUG(("%lu [%.*s] <- [%.*s%c", c->id, (int) opts->topic.len,
   348              (char *) opts->topic.buf,
   349              (int) (opts->message.len <= 10 ? opts->message.len : 10),
   350              (char *) opts->message.buf, opts->message.len <= 10 ? ']' : ' '));
   351    if (opts->qos > 0) len += 2;
   352    if (c->is_mqtt5) len += get_props_size(opts->props, opts->num_props);
   353
   354    if (opts->qos > 0 && id != 0) flags |= 1 << 3;
   355    if (!mqtt_send_header(c, MQTT_CMD_PUBLISH, flags, (uint32_t) len) ||
   356        !mg_send_u16(c, mg_htons((uint16_t) opts->topic.len)) ||
   357        !mg_send(c, opts->topic.buf, opts->topic.len))
   358      goto fail;
   359    if (opts->qos > 0) {  // need to send 'id' field
   360      if (id == 0) {      // generate new one if not resending
   361        if (++c->mgr->mqtt_id == 0) ++c->mgr->mqtt_id;
   362        id = c->mgr->mqtt_id;
   363      }
   364      if (!mg_send_u16(c, mg_htons(id))) goto fail;
   365    }
   366
   367    if (c->is_mqtt5 && !mg_send_mqtt_properties(c, opts->props, opts->num_props))
   368      goto fail;
   369
   370    if (opts->message.len > 0 &&
   371        !mg_send(c, opts->message.buf, opts->message.len))
   372      goto fail;
   373    return id;
   374
   375  fail:
   376    mg_error(c, "OOM");
   377    return id;
   378  }
