   394    if (!mg_send_u16(c, mg_htons((uint16_t) opts->topic.len)) ||
   395        !mg_send(c, opts->topic.buf, opts->topic.len))
   396      goto fail;
   397    if (is_sub && !mg_send(c, &qos_, sizeof(qos_))) goto fail;
   398    return;
   399  fail:
   400    mg_error(c, "OOM");
   401  }
